import os
import json

def count_lines_in_py_files(directory):
    line_counts = {}
    total_lines = 0
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                relative_path = os.path.relpath(file_path, directory)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                        line_count = len(lines)
                        line_counts[relative_path] = line_count
                        total_lines += line_count
                except Exception as e:
                    print(f"Error reading {file_path}: {e}")
    line_counts['total'] = total_lines
    return line_counts

if __name__ == "__main__":
    if len(os.sys.argv) != 2:
        print("Usage: python script.py <directory_path>")
    else:
        directory_path = os.sys.argv[1]
        if os.path.isdir(directory_path):
            result = count_lines_in_py_files(directory_path)
            print(json.dumps(result, indent=2))
        else:
            print("Invalid directory path provided.")
